/*
 * build_info.h -- which build is this, and for what? (both targets)
 *
 * A tester's screenshot or log has to answer that on its own; asking costs a
 * round trip and is often unanswerable later. src/build_info.c holds the
 * strings: the commit from include/swos_build.h (generated by
 * scripts/gen_build_info.sh) and the platform from the compiler's own macros.
 *
 * Shown in four places, so at least one survives however a report arrives:
 * the main menu's bottom line, the SDL window title, the [build] line in
 * SWOS.log, and --version.
 */
#ifndef BUILD_INFO_H
#define BUILD_INFO_H

/* "401ff14", or "401ff14-dirty" when tracked source differed from that commit
 * -- meaning the binary is NOT that commit. Lowercase, as git prints it. */
const char *Build_Id(void);

/* The commit's date, "2026-09-15". */
const char *Build_Date(void);

/* What this binary was built for: "linux x86-64", "windows x86-64",
 * "macos arm64", "amiga 68k" (or "amiga 68k aga"), "web", "switch".
 * The ONLY place the platform is decided -- don't detect it again elsewhere. */
const char *Build_Platform(void);

/* One line for a human: "OpenSWOS 401ff14 (2026-09-15, linux x86-64)".
 * Window title, SWOS.log and --version. */
const char *Build_Version(void);

/* The same facts for drawing with the in-game font, which has no lowercase
 * glyphs: "BUILD DD74714  2026-09-15  LINUX X86-64". */
const char *Build_ScreenText(void);

#endif /* BUILD_INFO_H */
